package com.hmdp.ai.runtime.retrieval;
import com.hmdp.ai.domain.knowledge.*;import org.springframework.stereotype.Component;import java.util.List;
@Component public class FallbackRrfReranker implements RerankService {private final RerankModelGateway gateway;public FallbackRrfReranker(RerankModelGateway gateway){this.gateway=gateway;}public RerankOutcome rerank(String tenant,String workspace,String profile,String query,List<KnowledgeChunk> chunks,List<Double> fallback){if(profile==null||profile.trim().isEmpty())return new RerankOutcome(fallback,"FALLBACK_RRF");try{List<String> docs=new java.util.ArrayList<>();for(KnowledgeChunk c:chunks)docs.add(c.getContent());return new RerankOutcome(gateway.rerank(tenant,workspace,profile,query,docs),"MODEL");}catch(Exception e){return new RerankOutcome(fallback,"FALLBACK_RRF");}}}
